def plain(text):
    return html.unescape(re.sub(r'<[^>]+>', '', text or ''))


def effect(number, kind, measure, description, before, after, unit, population,
           transition, replacement, source_quote, proposed_quote):
    assert source_quote in plain(by_number[number]['source_xml']), (number, 'source_quote', source_quote)
    assert proposed_quote in plain(out[number]['proposed_xml']), (number, 'proposed_quote', proposed_quote)
    return dict(kind=kind, measure_id=measure, description=description, before=before,
                after=after, unit=unit, affected_population=population,
                conditions_and_transition=transition,
                replacement_or_new_burdens=replacement,
                source_quote=source_quote, proposed_quote=proposed_quote)


def impact(number, classification, assessment, limitations, burdens, effects):
    assert len({e['measure_id'] for e in effects}) == len(effects), number
    out[number]['substantive_impact'] = dict(
        version=1, classification=classification, assessment=assessment,
        scope_limitations=limitations, new_burdens_review=burdens, effects=effects)


